<?php require 'config.php'; require 'lib.php'; need_login(); track_user(); csrf_check();
if(!is_admin()){ http_response_code(403); exit(t('Endast administratörer.','Administrators only.')); }
$APP=__DIR__;
// ---- hjälpfunktioner -------------------------------------------------------------------------
function upd_bdir(){ $p=dirname(__DIR__).'/vmmon-backups'; if((is_dir($p)||@mkdir($p,0750))&&is_writable($p)) return $p;
 $p=__DIR__.'/backups'; if(!is_dir($p)) @mkdir($p,0750); if(is_dir($p)){ @file_put_contents($p.'/.htaccess',"Require all denied\nDeny from all\n"); if(!is_file($p.'/index.html')) @file_put_contents($p.'/index.html',''); } return is_dir($p)&&is_writable($p)?$p:null; }
// filer som aldrig ersätts/säkerhetskopieras: nedladdade ikoner, lokal konfiguration, backuper, loggar
function upd_skip($rel){ return strpos($rel,'assets/icons/')===0||strpos($rel,'assets/chkicons/lib/')===0||$rel==='config.local.php'||strpos($rel,'backups/')===0||strpos($rel,'update_tmp/')===0||substr($rel,-4)==='.log'; }
function upd_ver($zf,&$prefix,&$err){ $err=''; $prefix=''; if(!class_exists('ZipArchive')){ $err=t('PHP-tillägget zip (ZipArchive) saknas på servern.','The PHP zip extension (ZipArchive) is missing on the server.'); return null; }
 $z=new ZipArchive; if($z->open($zf)!==true){ $err=t('Filen är ingen giltig zip-fil.','The file is not a valid zip file.'); return null; }
 for($i=0;$i<$z->numFiles;$i++) if(preg_match('~^([^/]+/)?config\.php$~',$z->getNameIndex($i),$m)){ $prefix=$m[1]??''; $c=$z->getFromIndex($i); if(preg_match("~VMMON_VERSION'\s*,\s*'([0-9][0-9.]*)'~",(string)$c,$v)){ $z->close(); return $v[1]; } }
 $z->close(); $err=t('Filen verkar inte vara en VM Monitor-release (config.php med version saknas).','The file does not look like a VM Monitor release (config.php with a version is missing).'); return null; }
function upd_entry($zf,$name){ $z=new ZipArchive; if($z->open($zf)!==true) return null; $c=$z->getFromName($name); $z->close(); return $c===false?null:$c; }
function upd_sqlfiles($zf,$prefix,$old,$new){ $z=new ZipArchive; $z->open($zf); $o=[]; for($i=0;$i<$z->numFiles;$i++){ if(preg_match('~^'.preg_quote($prefix,'~').'sql/(\d+\.\d+)\.sql$~',$z->getNameIndex($i),$m)&&version_compare($m[1],$old,'>')&&version_compare($m[1],$new,'<=')) $o[$m[1]]=$z->getNameIndex($i); } $z->close(); uksort($o,'version_compare'); $k=array_slice($o,-1,1,true); return $k; }
function upd_exec_sql($sql,&$log){ $pdo=db(); $sql=preg_replace('/^\s*--.*$/m','',$sql);
 foreach(preg_split('/;\s*(?:\r?\n|$)/',$sql) as $st){ $st=trim($st); if($st==='') continue; try{ $pdo->exec($st); }catch(PDOException $e){ $c=(int)($e->errorInfo[1]??0); if(in_array($c,[1050,1060,1061,1062,1068,1091],true)){ $log[]='  ↷ '.t('hoppade över (finns redan): ','skipped (already exists): ').substr(preg_replace('/\s+/',' ',$st),0,70); continue; } throw $e; } } }
function upd_extract($zf,$prefix,$app){ $z=new ZipArchive; if($z->open($zf)!==true) throw new Exception(t('Kan inte öppna zip-filen','Cannot open the zip file')); $n=0;
 for($i=0;$i<$z->numFiles;$i++){ $nm=$z->getNameIndex($i); if($prefix!==''&&strpos($nm,$prefix)!==0) continue; $rel=substr($nm,strlen($prefix)); if($rel===''||substr($rel,-1)==='/') continue;
  if(strpos($rel,'..')!==false||$rel[0]==='/'||strpos($rel,"\0")!==false||upd_skip($rel)) continue; $dst=$app.'/'.$rel; $dir=dirname($dst);
  if(!is_dir($dir)&&!@mkdir($dir,0755,true)) throw new Exception(t('Kan inte skapa mappen ','Cannot create folder ').dirname($rel)); $d=$z->getFromIndex($i); if($d===false) throw new Exception('zip: '.$rel);
  $tf=$dst.'.upd'.getmypid(); $mode=is_file($dst)?(@fileperms($dst)&0777):0664; if(@file_put_contents($tf,$d)===false){ @unlink($tf); if(@file_put_contents($dst,$d)===false) throw new Exception(t('Kan inte skriva ','Cannot write ').$rel); } else { @chmod($tf,$mode?:0664); if(!@rename($tf,$dst)){ @unlink($tf); if(@file_put_contents($dst,$d)===false) throw new Exception(t('Kan inte skriva ','Cannot write ').$rel); } } $n++; }
 $z->close(); return $n; }
// Databasdump i ren SQL (en sats per rad, så att den kan återläsas rad för rad utan SQL-tolk).
function upd_dump_db($file){ $pdo=db(); $h=@fopen($file,'wb'); if(!$h) throw new Exception(t('Kan inte skriva databasdumpen','Cannot write the database dump'));
 fwrite($h,"-- VM Monitor database dump ".date('Y-m-d H:i:s')." (version ".VMMON_VERSION.")\nSET FOREIGN_KEY_CHECKS=0;\nSET NAMES utf8mb4;\n");
 $tabs=$pdo->query("SHOW FULL TABLES WHERE Table_type='BASE TABLE'")->fetchAll(PDO::FETCH_NUM); $buf=$pdo->getAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY); $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,false);
 try{ foreach($tabs as $t0){ $t=$t0[0]; $q='`'.str_replace('`','``',$t).'`'; $cr=$pdo->query('SHOW CREATE TABLE '.$q)->fetchAll(PDO::FETCH_NUM)[0]; $ddl=preg_replace('/\s*\r?\n\s*/',' ',(string)$cr[1]);
   fwrite($h,"DROP TABLE IF EXISTS $q;\n$ddl;\n"); $rs=$pdo->query('SELECT * FROM '.$q); $rows=[]; $n=0;
   while($r=$rs->fetch(PDO::FETCH_NUM)){ $rows[]='('.implode(',',array_map(function($v) use($pdo){ return $v===null?'NULL':$pdo->quote((string)$v); },$r)).')'; if(count($rows)>=200){ fwrite($h,"INSERT INTO $q VALUES ".implode(',',$rows).";\n"); $rows=[]; } }
   $rs->closeCursor(); if($rows) fwrite($h,"INSERT INTO $q VALUES ".implode(',',$rows).";\n"); }
 } finally { $pdo->setAttribute(PDO::MYSQL_ATTR_USE_BUFFERED_QUERY,$buf); } fwrite($h,"SET FOREIGN_KEY_CHECKS=1;\n"); fclose($h); }
function upd_restore_db($zipf,&$log){ $z=new ZipArchive; if($z->open($zipf)!==true) throw new Exception(t('Kan inte öppna backupen','Cannot open the backup')); $st=$z->getStream('database.sql'); if(!$st){ $z->close(); throw new Exception(t('Backupen innehåller ingen databas.','The backup contains no database.')); }
 $pdo=db(); $n=0; while(($l=fgets($st))!==false){ $l=rtrim($l,"\r\n"); if($l===''||substr($l,0,2)==='--') continue; $pdo->exec($l); $n++; } fclose($st); $z->close(); $log[]='✔ '.sprintf(t('Databasen återställd (%d satser)','Database restored (%d statements)'),$n); }
function upd_backup($app,$bdir,$ver,$withdb=true){ $f=$bdir.'/vmmon-'.$ver.'-'.date('Ymd-His').'.zip'; $dump=null; $z=new ZipArchive; if($z->open($f,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true) throw new Exception(t('Kan inte skapa backupen','Cannot create the backup'));
 $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($app,FilesystemIterator::SKIP_DOTS)); foreach($it as $p){ if(!$p->isFile()) continue; $rel=ltrim(str_replace('\\','/',substr($p->getPathname(),strlen($app))),'/'); if(upd_skip($rel)) continue; $z->addFile($p->getPathname(),'vmmon/'.$rel); }
 if($withdb){ $td=$bdir.'/tmp'; if(!is_dir($td)) @mkdir($td,0750); $dump=$td.'/dump-'.bin2hex(random_bytes(4)).'.sql'; try{ upd_dump_db($dump); }catch(Throwable $e){ @unlink($dump); $z->close(); @unlink($f); throw new Exception(t('Databasbackupen misslyckades: ','The database backup failed: ').$e->getMessage()); } $z->addFile($dump,'database.sql'); }
 $ok=$z->close(); if($dump) @unlink($dump); if(!$ok||!is_file($f)) throw new Exception(t('Backupen kunde inte skrivas','The backup could not be written')); return $f; }
function upd_backups($bdir){ $o=[]; foreach(glob($bdir.'/vmmon-*.zip')?:[] as $f){ if(!preg_match('~/vmmon-([0-9][0-9.]*)-(\d{8}-\d{6})\.zip$~',$f,$m)) continue; $zz=new ZipArchive; $hd=$zz->open($f)===true&&$zz->locateName('database.sql')!==false; $zz->close(); $o[]=['f'=>$f,'n'=>basename($f),'v'=>$m[1],'d'=>$m[2],'s'=>filesize($f),'db'=>$hd]; } usort($o,fn($a,$b)=>strcmp($b['d'],$a['d'])); return $o; }
function upd_prune($bdir,$keep=3){ foreach(array_slice(upd_backups($bdir),$keep) as $b) @unlink($b['f']); }
function upd_notes($zf,$prefix,$old){ $r=upd_entry($zf,$prefix.'README.txt'); $o=[]; foreach(preg_split('/\r?\n/',(string)$r) as $l) if(preg_match('/^v(\d+\.\d+):\s*(.*)$/',$l,$m)&&version_compare($m[1],$old,'>')) $o[$m[1]]=$m[2]; uksort($o,fn($a,$b)=>version_compare($b,$a)); return $o; }
function upd_perms($app){ $bad=[]; $n=0; $it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($app,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::SELF_FIRST); $dirs=[$app];
 foreach($it as $p){ if($p->isDir()){ $rel=ltrim(str_replace('\\','/',substr($p->getPathname(),strlen($app))),'/').'/'; if(upd_skip($rel)) continue; $dirs[]=$p->getPathname(); } }
 foreach($dirs as $d){ $n++; if(!is_writable($d)||!is_executable($d)) $bad[]=$d; }
 $u=function_exists('posix_geteuid')?(posix_getpwuid(posix_geteuid())['name']??get_current_user()):get_current_user(); $gs=[]; if(function_exists('posix_getgroups')) foreach(posix_getgroups() as $g){ $i=posix_getgrgid($g); if($i) $gs[]=$i['name']; }
 $own=function_exists('posix_getpwuid')?(posix_getpwuid(fileowner($app))['name']??fileowner($app)):fileowner($app); $grp=function_exists('posix_getgrgid')?(posix_getgrgid(filegroup($app))['name']??filegroup($app)):filegroup($app);
 return ['bad'=>$bad,'n'=>$n,'user'=>$u,'groups'=>$gs,'owner'=>$own,'group'=>$grp,'mode'=>substr(sprintf('%o',fileperms($app)),-4)]; }
// Strömmad utskrift: sidan skickas rad för rad medan uppdateringen/backupen/återställningen pågår.
function upd_stream_start($title){ while(ob_get_level()) @ob_end_flush(); @ini_set('zlib.output_compression','0'); @ini_set('output_buffering','0'); @ini_set('implicit_flush','1'); if(!headers_sent()){ header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-cache'); header('X-Accel-Buffering: no'); } top($title); echo '<h2>'.h($title).'</h2><pre id="ul" style="white-space:pre-wrap;margin:0" class="card">'.str_repeat(' ',2048)."\n"; @flush(); }
function upd_now($m){ echo h($m)."\n"; @flush(); }
function upd_say(&$log,&$sent){ for(;$sent<count($log);$sent++) echo h($log[$sent])."\n"; @flush(); }
function upd_stream_end(){ echo '</pre><p class="mut">'.h(t('Klart – laddar resultatet…','Done – loading the result…')).' <a href="update.php">'.h(t('Fortsätt','Continue')).'</a></p><script>setTimeout(function(){location.replace("update.php")},1500)</script>'; bottom(); exit; }
function upd_done(){ if(function_exists('opcache_reset')) @opcache_reset(); }
