if(isset($_GET['dl'])&&$bdir){ $n=basename((string)$_GET['dl']); $f=$bdir.'/'.$n; if(preg_match('~^vmmon-[0-9][0-9.]*-\d{8}-\d{6}\.zip$~',$n)&&is_file($f)){ header('Content-Type: application/zip'); header('Content-Disposition: attachment; filename="'.$n.'"'); header('Content-Length: '.filesize($f)); readfile($f); exit; } http_response_code(404); exit; }
// ---- åtgärder
if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['a']??'';
 if($a==='upload'){ unset($_SESSION['upd_res']); if(!$tmp){ $_SESSION['upd_err']=t('Ingen skrivbar backupmapp hittades.','No writable backup folder was found.'); header('Location: update.php'); exit; }
  $fl=$_FILES['zip']??null; if(!$fl||$fl['error']!==UPLOAD_ERR_OK){ $_SESSION['upd_err']=t('Uppladdningen misslyckades (kod ','The upload failed (code ').($fl['error']??'?').t('). Kontrollera upload_max_filesize/post_max_size i php.ini.','). Check upload_max_filesize/post_max_size in php.ini.'); header('Location: update.php'); exit; }
  foreach(glob($tmp.'/upload-*.zip')?:[] as $o) @unlink($o); $dst=$tmp.'/upload-'.bin2hex(random_bytes(6)).'.zip';
  if(!move_uploaded_file($fl['tmp_name'],$dst)){ $_SESSION['upd_err']=t('Kunde inte spara den uppladdade filen.','Could not save the uploaded file.'); header('Location: update.php'); exit; }
  $v=upd_ver($dst,$pf,$er); if($v===null){ @unlink($dst); $_SESSION['upd_err']=$er; header('Location: update.php'); exit; }
  $_SESSION['upd']=['file'=>$dst,'ver'=>$v,'prefix'=>$pf]; header('Location: update.php'); exit; }
 if($a==='gh_check'){ unset($_SESSION['upd_res']); $repo=trim((string)($_POST['gh_repo']??'')); if($repo!==''&&!preg_match('~^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$~',$repo)){ $_SESSION['upd_err']=t('Ogiltigt repo-namn (använd ägare/repo).','Invalid repository name (use owner/repo).'); header('Location: update.php'); exit; } set_setting('gh_repo',$repo); $repo=$repo?:'';
  if($repo===''||!$tmp){ $_SESSION['upd_err']=$repo===''?t('Ange GitHub-repo (ägare/repo).','Enter the GitHub repository (owner/repo).'):t('Ingen skrivbar backupmapp hittades.','No writable backup folder was found.'); header('Location: update.php'); exit; }
  $gh=function($url,$file=null){ $c=curl_init($url); $fh=$file?fopen($file,'wb'):null; $o=[CURLOPT_FOLLOWLOCATION=>1,CURLOPT_MAXREDIRS=>5,CURLOPT_TIMEOUT=>120,CURLOPT_CONNECTTIMEOUT=>10,CURLOPT_USERAGENT=>'vmmon/'.VMMON_VERSION,CURLOPT_HTTPHEADER=>['Accept: application/vnd.github+json'],CURLOPT_PROTOCOLS=>CURLPROTO_HTTPS,CURLOPT_REDIR_PROTOCOLS=>CURLPROTO_HTTPS]; if($fh) $o[CURLOPT_FILE]=$fh; else $o[CURLOPT_RETURNTRANSFER]=1; curl_setopt_array($c,$o); $r=curl_exec($c); $code=curl_getinfo($c,CURLINFO_HTTP_CODE); $er=curl_error($c); curl_close($c); if($fh) fclose($fh); return [$code,$r,$er]; };
  [$code,$body,$er]=$gh('https://api.github.com/repos/'.$repo.'/releases/latest'); $j=$code===200?json_decode((string)$body,true):null;
  if(!is_array($j)||empty($j['tag_name'])){ $_SESSION['upd_err']=t('Kunde inte hämta senaste release från GitHub: ','Could not fetch the latest release from GitHub: ').($er?:"HTTP $code").($code===404?' – '.t('finns repot och minst en release?','does the repository and at least one release exist?'):''); header('Location: update.php'); exit; }
  $tag=ltrim((string)$j['tag_name'],'vV'); if(!preg_match('/^\d+(\.\d+)*$/',$tag)){ $_SESSION['upd_err']=t('Releasens tagg är inte ett versionsnummer: ','The release tag is not a version number: ').$j['tag_name']; header('Location: update.php'); exit; }
  if(!version_compare($tag,VMMON_VERSION,'>')){ $_SESSION['upd_err']=sprintf(t('Du har redan senaste versionen (%s). Senaste på GitHub: %s.','You already have the latest version (%s). Latest on GitHub: %s.'),VMMON_VERSION,$tag); header('Location: update.php'); exit; }
  $url=''; foreach((array)($j['assets']??[]) as $as){ if(preg_match('~^[Vv]mmon[_-].*\.zip$~',(string)($as['name']??''))&&!empty($as['browser_download_url'])){ $url=$as['browser_download_url']; break; } } if($url==='') $url=(string)($j['zipball_url']??'');
  if($url===''||strpos($url,'https://')!==0){ $_SESSION['upd_err']=t('Releasen saknar en zip-fil.','The release has no zip file.'); header('Location: update.php'); exit; }
  foreach(glob($tmp.'/upload-*.zip')?:[] as $o) @unlink($o); $dst=$tmp.'/upload-'.bin2hex(random_bytes(6)).'.zip'; [$code,,$er]=$gh($url,$dst);
  if($code!==200||!is_file($dst)||filesize($dst)<1000){ @unlink($dst); $_SESSION['upd_err']=t('Nedladdningen från GitHub misslyckades: ','The download from GitHub failed: ').($er?:"HTTP $code"); header('Location: update.php'); exit; }
  $v=upd_ver($dst,$pf,$er); if($v===null){ @unlink($dst); $_SESSION['upd_err']=$er; header('Location: update.php'); exit; }
  $_SESSION['upd']=['file'=>$dst,'ver'=>$v,'prefix'=>$pf]; header('Location: update.php'); exit; }
 if($a==='cancel'){ if(!empty($_SESSION['upd']['file'])) @unlink($_SESSION['upd']['file']); unset($_SESSION['upd'],$_SESSION['upd_res']); header('Location: update.php'); exit; }
 if($a==='install'&&!empty($_SESSION['upd'])&&$bdir){ set_time_limit(300); ignore_user_abort(true); $U=$_SESSION['upd']; $log=[]; $ok=false; $old=VMMON_VERSION; $new=$U['ver']; $sent=0; upd_stream_start(t('Uppdaterar VM Monitor','Updating VM Monitor'));
  try{ if(!is_file($U['file'])) throw new Exception(t('Den uppladdade filen finns inte kvar – ladda upp igen.','The uploaded file is gone – upload again.'));
   if(!version_compare($new,$old,'>')) throw new Exception(t('Den uppladdade versionen är inte nyare än den installerade.','The uploaded version is not newer than the installed one.'));
   upd_now('… '.t('Tar backup av filer och databas','Backing up files and database')); $bk=upd_backup($APP,$bdir,$old); $log[]='✔ '.t('Backup (filer + databas) skapad: ','Backup (files + database) created: ').basename($bk); upd_say($log,$sent);
   $sq=upd_sqlfiles($U['file'],$U['prefix'],$old,$new);
   upd_now('… '.t('Ersätter filer','Replacing files')); try{ $n=upd_extract($U['file'],$U['prefix'],$APP); $log[]='✔ '.sprintf(t('%d filer ersatta (ikoner och config.local.php rörs inte)','%d files replaced (icons and config.local.php are untouched)'),$n); upd_say($log,$sent); }
   catch(Throwable $e){ $log[]='✖ '.$e->getMessage(); try{ upd_extract($bk,'vmmon/',$APP); $log[]='↩ '.t('Filerna återställdes från backupen.','Files restored from the backup.'); }catch(Throwable $e2){ $log[]='✖ '.t('Återställningen misslyckades: ','Restore failed: ').$e2->getMessage(); } upd_say($log,$sent); throw new Exception(t('Uppdateringen avbröts.','The update was aborted.')); }
   upd_done();
   foreach($sq as $v=>$nm){ $log[]='▶ sql/'.$v.'.sql'; upd_say($log,$sent); try{ upd_exec_sql((string)upd_entry($U['file'],$nm),$log); $log[]='✔ sql/'.$v.'.sql'; upd_say($log,$sent); }catch(Throwable $e){ $log[]='✖ sql/'.$v.'.sql: '.$e->getMessage(); upd_say($log,$sent); throw new Exception(t('SQL-migreringen misslyckades. Filerna är redan ersatta – åtgärda felet och kör filen manuellt, eller återställ backupen nedan.','The SQL migration failed. The files are already replaced – fix the error and run the file manually, or restore the backup below.')); } }
   if(!$sq) $log[]='✔ '.t('Inga SQL-migreringar behövdes.','No SQL migrations were needed.'); $ok=true; @unlink($U['file']); unset($_SESSION['upd']); applog('info','config',"Updated VM Monitor $old -> $new"); upd_say($log,$sent);
  }catch(Throwable $e){ $log[]='✖ '.$e->getMessage(); upd_say($log,$sent); }
  $_SESSION['upd_res']=['ok'=>$ok,'log'=>$log,'old'=>$old,'new'=>$new]; upd_stream_end(); }
 if($a==='backup'&&$bdir){ set_time_limit(300); $log=[]; $ok=false; $sent=0; upd_stream_start(t('Tar backup','Backing up')); try{ upd_now('… '.t('Packar filer och dumpar databasen','Packing files and dumping the database')); $bk=upd_backup($APP,$bdir,VMMON_VERSION); $log[]='✔ '.t('Backup (filer + databas) skapad: ','Backup (files + database) created: ').basename($bk); $ok=true; applog('info','config','Backup created: '.basename($bk)); }catch(Throwable $e){ $log[]='✖ '.$e->getMessage(); } upd_say($log,$sent); $_SESSION['upd_res']=['ok'=>$ok,'log'=>$log,'old'=>VMMON_VERSION,'new'=>'','restore'=>1]; upd_stream_end(); }
 if($a==='delete'&&$bdir){ $n=basename((string)($_POST['bk']??'')); $f=$bdir.'/'.$n; $log=[]; $ok=false; if(preg_match('~^vmmon-[0-9][0-9.]*-\d{8}-\d{6}\.zip$~',$n)&&is_file($f)&&@unlink($f)){ $ok=true; $log[]='✔ '.t('Backup borttagen: ','Backup deleted: ').$n; applog('warning','config','Backup deleted: '.$n); } else $log[]='✖ '.t('Kunde inte ta bort backupen.','Could not delete the backup.'); $_SESSION['upd_res']=['ok'=>$ok,'log'=>$log,'old'=>VMMON_VERSION,'new'=>'','restore'=>1]; header('Location: update.php'); exit; }
 if($a==='restore'&&$bdir){ set_time_limit(300); $n=basename((string)($_POST['bk']??'')); $f=$bdir.'/'.$n; $log=[]; $ok=false; $sent=0; upd_stream_start(t('Återställer backup','Restoring backup'));
