  }catch(Throwable $e){ $log[]='✖ '.$e->getMessage(); } upd_say($log,$sent);
  $_SESSION['upd_res']=['ok'=>$ok,'log'=>$log,'old'=>VMMON_VERSION,'new'=>'','restore'=>1]; upd_stream_end(); }
 header('Location: update.php'); exit; }
