<script>(function(){var el=document.getElementById('wst'),n=0,first=null,sv=<?= json_encode(lang()==='sv') ?>;function T(a,b){return sv?a:b}
function tick(){fetch('api/worker.php',{credentials:'same-origin'}).then(function(r){return r.json()}).then(function(d){var a=d.age;if(first===null)first=a;
 if(a===null){el.textContent=T('Bakgrundsprocessen: ingen puls sedan tidigare.','Background process: no heartbeat recorded.')}
 else if(a<=20){el.innerHTML='<span class="okt">✔</span> '+T('Bakgrundsprocessen kör (senaste puls för ','Background process is running (last heartbeat ')+a+T(' s sedan).',' s ago).')}
 else if(n<30){el.textContent=T('Bakgrundsprocessen startar om… (senaste puls för ','Background process is restarting… (last heartbeat ')+a+T(' s sedan)',' s ago)')}
 else{el.innerHTML='<span class="badt">'+T('Ingen puls från bakgrundsprocessen – kontrollera tjänsten: sudo systemctl restart vmmon-worker','No heartbeat from the background process – check the service: sudo systemctl restart vmmon-worker')+'</span>';return}
 if(++n<40)setTimeout(tick,a!==null&&a<=20&&n>3?60000:3000)}).catch(function(){if(++n<40)setTimeout(tick,5000)})}
tick()})();</script><?php endif; ?></div><?php endif; ?>
